        position: 'Data Scientist',
        requiredSkills: ['Python', 'Machine Learning', 'SQL'],
      });

      const result = await agent.execute(task);

      expect(result.status).toBe('success');
      expect(result.data.topCandidates).toBeDefined();
    });
  });

