    expect(workspaceMock.performSheetOperation).toHaveBeenCalledWith(expect.objectContaining({
      operation: 'append',
      spreadsheetId: 'test-sheet-id',
      values: expect.arrayContaining([expect.arrayContaining(['INV-002', 'Sheet Vendor', 2000])])
    }));
